@register.filter
def social_icon(icon_key):
    from django.utils.safestring import mark_safe
    return mark_safe(SOCIAL_ICONS_SVG.get(icon_key or 'link', SOCIAL_ICONS_SVG['link']))


@register.simple_tag
def social_icon_tag(icon_key):
    from django.utils.safestring import mark_safe
    return mark_safe(SOCIAL_ICONS_SVG.get(icon_key or 'link', SOCIAL_ICONS_SVG['link']))